import sqlite3
def verify_contract():
    db = sqlite3.connect(':memory:')
    db.execute('CREATE TABLE items (id TEXT UNIQUE, value TEXT)')
    db.execute("INSERT INTO items VALUES ('key', 'value')")
    assert db.execute('SELECT value FROM items').fetchone() == ('value',)
    try:
        db.execute("INSERT INTO items VALUES ('key', 'different')")
    except sqlite3.IntegrityError:
        pass
    else:
        raise AssertionError('unique contract lost')

